/// <summary>
/// This methos used for while inserting manipulate data.
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
/// <returns></returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean     ret;
    DataAreaId  dataAreaId = _dataSourceCtx.getBuffer().DataAreaId;

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustomerAttributeValueEntity, CustomerInstanceValue))
    {
        CustomerInstanceValue customerInstanceValue = _dataSourceCtx.getBuffer();
        dataAreaId = customerInstanceValue.CustomerDataAreaId;
    }

    changecompany(dataAreaId)
    {
        ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);
    }

    return ret;      
}
